import { useEffect, useRef } from 'react';
import { createPortal } from 'react-dom';

import { ModalBody } from './ModalBody';
import { ModalDescription } from './ModalDescription';
import { ModalFooter } from './ModalFooter';
import { ModalHeader } from './ModalHeader';
import { ModalTitle } from './ModalTitle';

import { useRakitConfig, getComponentIdentifier } from '../../../config/RakitContext';
import { cn } from '../../../utils/ui/cn';

import type { ModalProps, ModalSize } from '../../../types/ui/modal.types';

const sizeClasses: Record<ModalSize, string> = {
  xs: 'max-w-xs sm:max-w-sm',
  sm: 'max-w-sm sm:max-w-md',
  md: 'max-w-md sm:max-w-lg',
  lg: 'max-w-lg sm:max-w-2xl',
  xl: 'max-w-2xl sm:max-w-4xl',
  '2xl': 'max-w-2xl sm:max-w-4xl',
  full: 'max-w-6xl w-[95vw]',
};

export function Modal({
  id,
  isOpen,
  onClose,
  title,
  description,
  icon,
  children,
  footer,
  size = 'md',
  className = '',
  contentClassName = '',
  closeOnEsc = true,
  closeOnOverlayClick = true,
  showCloseButton = true,
  backdropBlur = true,
  trapFocus = true,
}: ModalProps) {
  const config = useRakitConfig();
  const identifier = getComponentIdentifier('modal', config, id);
  const modalOverride = config.components?.modal;

  const modalRef = useRef<HTMLDivElement>(null);
  const previousActiveElement = useRef<HTMLElement | null>(null);

  useEffect(() => {
    if (!isOpen) return;

    // Retain previous active element for focus restoration
    if (typeof document !== 'undefined') {
      previousActiveElement.current = document.activeElement as HTMLElement;
    }

    // Auto-focus first focusable element inside modal
    if (trapFocus && modalRef.current) {
      const focusableSelectors = [
        'a[href]',
        'button:not([disabled])',
        'textarea:not([disabled])',
        'input:not([disabled])',
        'select:not([disabled])',
        '[tabindex]:not([tabindex="-1"])',
      ].join(', ');

      const focusables = modalRef.current.querySelectorAll<HTMLElement>(focusableSelectors);
      if (focusables.length > 0) {
        requestAnimationFrame(() => {
          focusables[0]?.focus();
        });
      } else {
        modalRef.current.focus();
      }
    }

    const handleKeyDown = (e: KeyboardEvent) => {
      // Escape key dismissal
      if (closeOnEsc && e.key === 'Escape') {
        e.stopPropagation();
        onClose();
        return;
      }

      // Trap focus cycling on Tab / Shift+Tab
      if (trapFocus && e.key === 'Tab' && modalRef.current) {
        const focusableSelectors = [
          'a[href]',
          'button:not([disabled])',
          'textarea:not([disabled])',
          'input:not([disabled])',
          'select:not([disabled])',
          '[tabindex]:not([tabindex="-1"])',
        ].join(', ');

        const focusables = Array.from(modalRef.current.querySelectorAll<HTMLElement>(focusableSelectors));
        if (focusables.length === 0) {
          e.preventDefault();
          return;
        }

        const first = focusables[0];
        const last = focusables[focusables.length - 1];

        if (e.shiftKey) {
          if (document.activeElement === first || !modalRef.current.contains(document.activeElement)) {
            e.preventDefault();
            last.focus();
          }
        } else {
          if (document.activeElement === last || !modalRef.current.contains(document.activeElement)) {
            e.preventDefault();
            first.focus();
          }
        }
      }
    };

    window.addEventListener('keydown', handleKeyDown);
    const originalOverflow = document.body.style.overflow;
    document.body.style.overflow = 'hidden';

    return () => {
      window.removeEventListener('keydown', handleKeyDown);
      document.body.style.overflow = originalOverflow;
      if (previousActiveElement.current && typeof previousActiveElement.current.focus === 'function') {
        previousActiveElement.current.focus();
      }
    };
  }, [isOpen, closeOnEsc, onClose, trapFocus]);

  if (!isOpen || typeof document === 'undefined') return null;

  const content = (
    <div
      id={identifier.id}
      data-rakit={identifier['data-rakit']}
      className={cn(
        'rakit-modal fixed inset-0 z-50 flex items-center justify-center p-4 overflow-y-auto',
        identifier.className,
        modalOverride?.className,
        className
      )}
      style={modalOverride?.style}
      role="dialog"
      aria-modal="true"
    >
      {/* Synchronized Backdrop Overlay */}
      <div
        className={cn(
          'rakit-modal-overlay fixed inset-0 bg-slate-900/60 transition-opacity animate-in fade-in duration-200',
          backdropBlur && 'backdrop-blur-xs'
        )}
        onClick={() => {
          if (closeOnOverlayClick) onClose();
        }}
        aria-hidden="true"
      />

      {/* Modal Dialog Content Panel */}
      <div
        ref={modalRef}
        tabIndex={-1}
        className={cn(
          'rakit-modal-content relative z-10 w-full bg-white dark:bg-slate-900 text-slate-900 dark:text-slate-100 rounded-2xl shadow-2xl border border-slate-200/90 dark:border-slate-800 overflow-hidden flex flex-col focus:outline-hidden transition-all animate-in zoom-in-95 fade-in duration-200',
          sizeClasses[size],
          contentClassName
        )}
        onClick={e => e.stopPropagation()}
      >
        {(title || showCloseButton) && (
          <ModalHeader onClose={showCloseButton ? onClose : undefined}>
            <div className="flex items-center gap-2.5">
              {icon && <div className="text-emerald-600 shrink-0">{icon}</div>}
              <div>
                {title && <ModalTitle>{title}</ModalTitle>}
                {description && <ModalDescription>{description}</ModalDescription>}
              </div>
            </div>
          </ModalHeader>
        )}

        {/* If title and footer are not used, allow children full control (compound layout), otherwise wrap in ModalBody */}
        {title || footer ? (
          <ModalBody>{children}</ModalBody>
        ) : (
          <div className="flex-1 flex flex-col min-h-0 overflow-hidden">{children}</div>
        )}

        {footer && <ModalFooter>{footer}</ModalFooter>}
      </div>
    </div>
  );

  return createPortal(content, document.body);
}

// ============================================================================
// SUB-COMPONENTS & COMPOUND ATTACHMENTS
// ============================================================================
Modal.Header = ModalHeader;
Modal.Title = ModalTitle;
Modal.Description = ModalDescription;
Modal.Body = ModalBody;
Modal.Footer = ModalFooter;

export { ModalHeader } from './ModalHeader';
export { ModalTitle } from './ModalTitle';
export { ModalDescription } from './ModalDescription';
export { ModalBody } from './ModalBody';
export { ModalFooter } from './ModalFooter';

// ============================================================================
// TYPES & INTERFACES
// ============================================================================
export type { ModalProps, ModalSize } from '../../../types/ui/modal.types';

