import { useState } from 'react';

import { cn } from '../../../utils/ui/cn';

import type {
  SegmentedControlProps,
  SegmentedControlSize,
} from '../../../types/ui/segmented-control.types';

const containerSizeStyles: Record<SegmentedControlSize, string> = {
  xs: 'p-0.5 rounded-lg gap-0.5',
  sm: 'p-0.5 rounded-lg gap-1',
  md: 'p-1 rounded-xl gap-1',
  lg: 'p-1 rounded-xl gap-1.5',
};

const itemSizeStyles: Record<SegmentedControlSize, { button: string; icon: string }> = {
  xs: {
    button: 'px-2 py-0.5 text-xs font-medium rounded-md gap-1 h-6',
    icon: 'w-3 h-3',
  },
  sm: {
    button: 'px-2.5 py-1 text-xs font-medium rounded-md gap-1.5 h-7',
    icon: 'w-3.5 h-3.5',
  },
  md: {
    button: 'px-3.5 py-1 text-sm font-medium rounded-lg gap-2 h-8',
    icon: 'w-4 h-4',
  },
  lg: {
    button: 'px-4 py-1.5 text-base font-medium rounded-lg gap-2.5 h-9',
    icon: 'w-4.5 h-4.5',
  },
};

export function SegmentedControl<T extends string = string>({
  items = [],
  value,
  defaultValue,
  onChange,
  size = 'md',
  orientation = 'horizontal',
  fullWidth = false,
  disabled = false,
  theme = 'light',
  className = '',
  itemClassName = '',
}: SegmentedControlProps<T>) {
  const isDark = theme === 'dark';
  const isVertical = orientation === 'vertical';
  const initialValue = defaultValue || items[0]?.value || ('' as T);
  const [internalValue, setInternalValue] = useState<T>(initialValue);

  const activeValue = value !== undefined ? value : internalValue;

  const handleClick = (itemValue: T, itemDisabled?: boolean) => {
    if (disabled || itemDisabled) return;
    if (value === undefined) {
      setInternalValue(itemValue);
    }
    onChange?.(itemValue);
  };

  return (
    <div
      role="group"
      aria-orientation={orientation}
      data-rakit="segmented-control"
      className={cn(
        'rakit-segmented-control inline-flex select-none transition-colors border',
        isVertical ? 'flex-col' : 'items-center',
        fullWidth ? 'w-full' : '',
        containerSizeStyles[size],
        isDark
          ? 'bg-slate-800/80 border-slate-700/60'
          : 'bg-slate-100/90 border-slate-200/70',
        disabled ? 'opacity-50 cursor-not-allowed pointer-events-none' : '',
        className
      )}
    >
      {items.map((item) => {
        const isActive = item.value === activeValue;
        const isItemDisabled = disabled || item.disabled;

        return (
          <button
            key={item.value}
            type="button"
            role="radio"
            title={item.title}
            aria-label={item.title || (typeof item.label === 'string' ? item.label : undefined)}
            aria-checked={isActive}
            disabled={isItemDisabled}
            onClick={() => handleClick(item.value, item.disabled)}
            className={cn(
              'relative inline-flex items-center justify-center transition-all duration-150',
              fullWidth ? 'flex-1' : '',
              itemSizeStyles[size].button,
              isItemDisabled ? 'opacity-40 cursor-not-allowed' : 'cursor-pointer',
              isActive
                ? isDark
                  ? 'bg-slate-700 text-white shadow-2xs font-semibold'
                  : 'bg-white text-slate-900 shadow-2xs font-semibold'
                : isDark
                  ? 'text-slate-400 hover:text-white hover:bg-slate-700/40'
                  : 'text-slate-600 hover:text-slate-900 hover:bg-slate-200/50',
              itemClassName
            )}
          >
            {item.icon && (
              <span className={cn('shrink-0', itemSizeStyles[size].icon)}>
                {item.icon}
              </span>
            )}
            {item.label && <span className="truncate">{item.label}</span>}
          </button>
        );
      })}
    </div>
  );
}

export type {
  SegmentedControlItem,
  SegmentedControlProps,
  SegmentedControlSize,
  SegmentedControlOrientation,
} from '../../../types/ui/segmented-control.types';
