import React from 'react';
import { LinkTextProps } from '../../../types/ui/typography.types';
import { useRakitConfig, getComponentIdentifier } from '../../../config/RakitContext';

export const LinkText: React.FC<LinkTextProps> = ({
  href,
  external = false,
  underline = 'hover',
  id,
  className = '',
  children,
  target,
  rel,
  ...props
}) => {
  const config = useRakitConfig();
  const identifier = getComponentIdentifier('link', config, id);

  const underlineClasses: Record<string, string> = {
    always: 'underline underline-offset-4',
    hover: 'hover:underline underline-offset-4',
    none: 'no-underline',
  };

  const finalTarget = external ? '_blank' : target;
  const finalRel = external ? (rel || 'noopener noreferrer') : rel;

  const classes = [
    'rakit-link inline-flex items-center gap-1 font-medium text-emerald-600 hover:text-emerald-700 dark:text-emerald-400 dark:hover:text-emerald-300 transition-colors duration-150 cursor-pointer',
    underlineClasses[underline],
    identifier.className,
    className,
  ]
    .filter(Boolean)
    .join(' ');

  return (
    <a
      id={identifier.id}
      href={href}
      target={finalTarget}
      rel={finalRel}
      className={classes}
      data-rakit={identifier['data-rakit']}
      {...props}
    >
      {children}
      {external && (
        <svg
          className="w-3.5 h-3.5 opacity-70"
          fill="none"
          stroke="currentColor"
          viewBox="0 0 24 24"
          aria-hidden="true"
        >
          <path
            strokeLinecap="round"
            strokeLinejoin="round"
            strokeWidth={2}
            d="M10 6H6a2 2 0 00-2 2v10a2 2 0 002 2h10a2 2 0 002-2v-4M14 4h6m0 0v6m0-6L10 14"
          />
        </svg>
      )}
    </a>
  );
};
