import { cn } from '../../../utils/ui/cn';
import { useSidebar } from './SidebarContext';
import type { SidebarNavProps } from '../../../types/ui/sidebar.types';

export function SidebarNav({ className = '', children, ...rest }: SidebarNavProps) {
  const { collapsed } = useSidebar();

  return (
    <nav
      className={cn(
        'rakit-sidebar-nav flex-1 min-h-0 overflow-y-auto space-y-4 transition-all duration-200',
        collapsed ? 'px-1.5 py-2' : 'px-3 py-2.5',
        className
      )}
      data-rakit="sidebar-nav"
      data-collapsed={collapsed}
      {...rest}
    >
      {children}
    </nav>
  );
}
