import { cn } from '../../../utils/ui/cn';
import { useRakitConfig, getComponentIdentifier } from '../../../config/RakitContext';
import type { HeadingProps, HeadingLevel, HeadingSize, TextColor, TextWeight } from '../../../types/ui/typography.types';

const defaultLevelSizes: Record<HeadingLevel, HeadingSize> = {
  h1: '3xl',
  h2: '2xl',
  h3: 'xl',
  h4: 'lg',
  h5: 'md',
  h6: 'sm',
};

const sizeClasses: Record<HeadingSize, string> = {
  xs: 'text-xs',
  sm: 'text-sm',
  md: 'text-base',
  lg: 'text-lg',
  xl: 'text-xl sm:text-2xl',
  '2xl': 'text-2xl sm:text-3xl',
  '3xl': 'text-3xl sm:text-4xl',
  '4xl': 'text-4xl sm:text-5xl',
};

const weightClasses: Record<TextWeight, string> = {
  light: 'font-light',
  normal: 'font-normal',
  medium: 'font-medium',
  semibold: 'font-semibold',
  bold: 'font-bold',
  extrabold: 'font-extrabold',
};

const colorClasses: Record<TextColor, string> = {
  default: 'text-slate-900 dark:text-slate-100',
  secondary: 'text-slate-700 dark:text-slate-300',
  muted: 'text-slate-500 dark:text-slate-400',
  primary: 'text-emerald-700 dark:text-emerald-400',
  success: 'text-emerald-600 dark:text-emerald-400',
  warning: 'text-amber-700 dark:text-amber-400',
  danger: 'text-rose-700 dark:text-rose-400',
  info: 'text-sky-700 dark:text-sky-400',
  inverse: 'text-white dark:text-slate-900',
};

const trackingClasses = {
  tighter: 'tracking-tighter',
  tight: 'tracking-tight',
  normal: 'tracking-normal',
  wide: 'tracking-wide',
  wider: 'tracking-wider',
};

export function Heading({
  as: Component = 'h2',
  size,
  weight,
  color = 'default',
  tracking = 'tight',
  className = '',
  id,
  children,
  ...props
}: HeadingProps) {
  const config = useRakitConfig();
  const identifier = getComponentIdentifier('heading', config, id);

  const resolvedSize = size || defaultLevelSizes[Component];
  const defaultWeight: TextWeight =
    resolvedSize === '4xl' || resolvedSize === '3xl' || resolvedSize === '2xl'
      ? 'extrabold'
      : resolvedSize === 'xl' || resolvedSize === 'lg'
      ? 'bold'
      : 'semibold';
  const resolvedWeight = weight || defaultWeight;

  return (
    <Component
      id={identifier.id}
      data-rakit={identifier['data-rakit']}
      className={cn(
        'rakit-heading font-display leading-tight',
        identifier.className,
        sizeClasses[resolvedSize],
        weightClasses[resolvedWeight],
        colorClasses[color],
        trackingClasses[tracking],
        className
      )}
      {...props}
    >
      {children}
    </Component>
  );
}
