import React from 'react';
import { BreadcrumbItemProps } from '../../../types/ui/breadcrumb.types';

export const BreadcrumbItem: React.FC<BreadcrumbItemProps> = ({
  active = false,
  className = '',
  children,
  ...props
}) => {
  const classes = [
    'rakit-breadcrumb-item inline-flex items-center gap-1.5',
    active ? 'font-medium text-slate-900 dark:text-slate-100' : 'text-slate-500 dark:text-slate-400',
    className,
  ]
    .filter(Boolean)
    .join(' ');

  return (
    <li className={classes} data-rakit="breadcrumb-item" {...props}>
      {children}
    </li>
  );
};
