import { useState, useMemo } from 'react';
import type { ReactNode } from 'react';
import { FileCode, FileJson, FileText } from 'lucide-react';

import { CodeEditor } from './CodeEditor';

import type {
  CodeEditorLanguage,
  CodeEditorProps,
} from '../../../types/ui/code-editor.types';
import type { TabItem } from '../../../types/ui/tabs.types';

export interface CodeViewerFile {
  name: string;
  content: string;
  language?: CodeEditorLanguage;
  icon?: ReactNode;
}

export interface CodeViewerProps extends Partial<CodeEditorProps> {
  value?: string;
  files?: CodeViewerFile[];
  activeFileName?: string;
  onActiveFileChange?: (fileName: string) => void;
}

function detectLanguage(fileName: string): CodeEditorLanguage {
  const ext = fileName.split('.').pop()?.toLowerCase() || '';
  switch (ext) {
    case 'tsx':
      return 'tsx';
    case 'ts':
      return 'ts';
    case 'jsx':
      return 'jsx';
    case 'js':
    case 'mjs':
    case 'cjs':
      return 'js';
    case 'html':
    case 'htm':
      return 'html';
    case 'css':
      return 'css';
    case 'json':
      return 'json';
    default:
      return 'text';
  }
}

function detectFileIcon(fileName: string): ReactNode {
  const ext = fileName.split('.').pop()?.toLowerCase() || '';
  switch (ext) {
    case 'json':
      return <FileJson className="w-3.5 h-3.5 text-emerald-500" />;
    case 'tsx':
    case 'jsx':
      return <FileCode className="w-3.5 h-3.5 text-cyan-500" />;
    case 'ts':
    case 'js':
    case 'mjs':
    case 'cjs':
      return <FileCode className="w-3.5 h-3.5 text-amber-500" />;
    case 'html':
    case 'htm':
      return <FileCode className="w-3.5 h-3.5 text-orange-500" />;
    default:
      return <FileText className="w-3.5 h-3.5 text-slate-400" />;
  }
}

export function CodeViewer({
  value = '',
  files,
  activeFileName,
  onActiveFileChange,
  language = 'tsx',
  title,
  theme = 'light',
  height = 'auto',
  maxHeight = '480px',
  showToolbar = true,
  showCopyButton = true,
  showLineNumbers = true,
  className = '',
  tabsVariant = 'pills',
  ...props
}: CodeViewerProps) {
  const hasFiles = Boolean(files && files.length > 0);

  // Internal tab state if multi-file mode
  const [internalActiveFile, setInternalActiveFile] = useState<string>(() => {
    return files && files.length > 0 ? files[0].name : '';
  });

  const currentFileName = activeFileName !== undefined ? activeFileName : internalActiveFile;

  const currentFile = useMemo(() => {
    if (!hasFiles || !files) return null;
    return files.find((f) => f.name === currentFileName) || files[0];
  }, [hasFiles, files, currentFileName]);

  const fileTabs: TabItem[] | undefined = useMemo(() => {
    if (!hasFiles || !files) return undefined;
    return files.map((file) => ({
      id: file.name,
      label: file.name,
      icon: file.icon || detectFileIcon(file.name),
    }));
  }, [hasFiles, files]);

  const handleTabChange = (tabId: string) => {
    if (activeFileName === undefined) {
      setInternalActiveFile(tabId);
    }
    onActiveFileChange?.(tabId);
  };

  // Determine active code and language
  const resolvedValue = hasFiles ? currentFile?.content ?? '' : value;
  const resolvedLanguage = hasFiles
    ? currentFile?.language || detectLanguage(currentFile?.name || '')
    : language;
  const resolvedTitle = title !== undefined ? title : hasFiles ? undefined : undefined;

  return (
    <CodeEditor
      value={resolvedValue}
      language={resolvedLanguage}
      title={resolvedTitle}
      theme={theme}
      readOnly
      height={height}
      maxHeight={maxHeight}
      showToolbar={showToolbar}
      showCopyButton={showCopyButton}
      showLineNumbers={showLineNumbers}
      showViewToggle={resolvedLanguage === 'json'}
      tabs={fileTabs}
      activeTab={currentFile?.name}
      onChangeTab={handleTabChange}
      tabsVariant={tabsVariant}
      className={className}
      {...props}
    />
  );
}

export const FileViewer = CodeViewer;
export type FileViewerProps = CodeViewerProps;
