import { createContext, useContext, useMemo } from 'react';
import type { RakitConfig, RakitProviderProps } from '../types/ui/config.types';

export const DEFAULT_RAKIT_CONFIG: RakitConfig = {
  prefix: 'rakit',
  enableIdentifiers: true,
  theme: 'light',
  components: {},
};

export const RakitContext = createContext<RakitConfig>(DEFAULT_RAKIT_CONFIG);

export function RakitProvider({ config = {}, children }: RakitProviderProps) {
  const mergedConfig = useMemo<RakitConfig>(() => {
    return {
      ...DEFAULT_RAKIT_CONFIG,
      ...config,
      components: {
        ...DEFAULT_RAKIT_CONFIG.components,
        ...(config.components || {}),
      },
    };
  }, [config]);

  return (
    <RakitContext.Provider value={mergedConfig}>
      {children}
    </RakitContext.Provider>
  );
}

export function useRakitConfig(): RakitConfig {
  const context = useContext(RakitContext);
  return context || DEFAULT_RAKIT_CONFIG;
}

export function defineRakitConfig(config: RakitConfig): RakitConfig {
  return config;
}

/**
 * Helper untuk menyusun class identifier dan atribut data-rakit.
 */
export function getComponentIdentifier(
  componentName: string,
  config?: RakitConfig,
  customId?: string
) {
  const prefix = config?.prefix || 'rakit';
  const enabled = config?.enableIdentifiers !== false;

  if (!enabled) {
    return {
      className: '',
      'data-rakit': componentName,
      ...(customId ? { id: customId } : {}),
    };
  }

  return {
    className: `${prefix}-${componentName}`,
    'data-rakit': componentName,
    ...(customId ? { id: customId } : {}),
  };
}
