import { isValidElement } from 'react';
import { X } from 'lucide-react';
import { cn } from '../../../utils/ui/cn';
import { useSidebar } from './SidebarContext';
import type { SidebarHeaderProps } from '../../../types/ui/sidebar.types';

export function SidebarHeader({
  title,
  subtitle,
  icon: Icon,
  action,
  showCloseButton = true,
  onClose: propOnClose,
  className = '',
  children,
  ...rest
}: SidebarHeaderProps) {
  const context = useSidebar();
  const isCollapsed = context.collapsed;
  const handleClose = propOnClose || context.onClose;

  if (children) {
    return (
      <div
        className={cn(
          'rakit-sidebar-header flex items-center shrink-0 transition-all duration-200',
          isCollapsed ? 'justify-center p-2' : 'justify-between px-3.5 py-3',
          'border-b border-slate-100 dark:border-slate-800/80',
          className
        )}
        data-rakit="sidebar-header"
        data-collapsed={isCollapsed}
        {...rest}
      >
        {children}
      </div>
    );
  }

  const renderIcon = () => {
    if (!Icon) return null;
    if (isValidElement(Icon)) return Icon;
    const IconComponent = Icon as React.ComponentType<{ className?: string }>;
    return <IconComponent className="w-5 h-5 shrink-0 text-emerald-600 dark:text-emerald-400" />;
  };

  // If collapsed and action provided (e.g. Sidebar.Toggle), show only action centered
  if (isCollapsed && action) {
    return (
      <div
        className={cn(
          'rakit-sidebar-header flex items-center justify-center p-2 shrink-0 transition-all duration-200',
          'border-b border-slate-100 dark:border-slate-800/80',
          className
        )}
        data-rakit="sidebar-header"
        data-collapsed={true}
        {...rest}
      >
        {action}
      </div>
    );
  }

  return (
    <div
      className={cn(
        'rakit-sidebar-header flex items-center shrink-0 transition-all duration-200',
        isCollapsed ? 'justify-center p-2' : 'justify-between px-3.5 py-3',
        'border-b border-slate-100 dark:border-slate-800/80',
        className
      )}
      data-rakit="sidebar-header"
      data-collapsed={isCollapsed}
      {...rest}
    >
      <div className={cn('flex items-center gap-2.5 min-w-0', isCollapsed && 'justify-center')}>
        {renderIcon()}
        {!isCollapsed && (title || subtitle) && (
          <div className="flex flex-col min-w-0 leading-tight">
            {title && (
              <span className="font-semibold text-xs tracking-tight text-slate-800 dark:text-slate-100 truncate">
                {title}
              </span>
            )}
            {subtitle && (
              <span className="text-[10px] text-slate-500 dark:text-slate-400 truncate">
                {subtitle}
              </span>
            )}
          </div>
        )}
      </div>

      <div className="flex items-center gap-1.5 shrink-0">
        {action && <div className="hidden md:flex items-center">{action}</div>}

        {showCloseButton && handleClose && (
          <button
            type="button"
            onClick={handleClose}
            aria-label="Tutup Sidebar"
            className="md:hidden p-1 rounded-md text-slate-400 hover:text-slate-700 hover:bg-slate-100 dark:hover:bg-slate-800 dark:hover:text-slate-200 transition-colors cursor-pointer"
          >
            <X className="w-4 h-4" />
          </button>
        )}
      </div>
    </div>
  );
}
