import { forwardRef, useId, useState } from 'react';
import { X } from 'lucide-react';

import { FieldWrapper } from '../field-wrapper';
import { cn } from '../../../../utils/ui/cn';
import { useRakitConfig, getComponentIdentifier } from '../../../../config/RakitContext';

import type { TextAreaProps } from '../../../../types/ui/field/textArea.types';
import type { FieldSize } from '../../../../types/ui/field/fieldWrapper.types';

export const TextArea = forwardRef<HTMLTextAreaElement, TextAreaProps>(
  (
    {
      id: customId,
      name,
      value,
      defaultValue,
      onChange,
      placeholder,
      rows = 4,
      maxLength,
      showCount = false,
      disabled,
      readOnly,
      required,
      optional,
      label,
      error,
      helperText,
      hint,
      size,
      layout = 'vertical',
      clearable,
      onClear,
      wrapperClassName,
      className,
      ...props
    },
    ref
  ) => {
    const config = useRakitConfig();
    const fieldConfig = config?.components?.field;
    const resolvedSize: FieldSize = size || fieldConfig?.defaultSize || 'md';

    const generatedId = useId();
    const textareaId = customId || generatedId;
    const identifier = getComponentIdentifier('textarea', config, customId);

    const [internalValue, setInternalValue] = useState<string>(
      typeof defaultValue === 'string' ? defaultValue : ''
    );
    const isControlled = value !== undefined;
    const currentValue = isControlled ? String(value ?? '') : internalValue;
    const currentLength = currentValue.length;
    const hasValue = currentLength > 0;

    const handleChange = (e: React.ChangeEvent<HTMLTextAreaElement>) => {
      if (!isControlled) {
        setInternalValue(e.target.value);
      }
      onChange?.(e);
    };

    const handleClear = () => {
      if (!isControlled) {
        setInternalValue('');
      }
      onClear?.();
    };

    const sizeClasses: Record<FieldSize, string> = {
      xs: 'p-2 text-xs min-h-[56px]',
      sm: 'p-2.5 text-xs min-h-[72px]',
      md: 'p-3 text-sm min-h-[96px]',
      lg: 'p-3.5 text-base min-h-[120px]',
      xl: 'p-4 text-lg min-h-[144px]',
    };

    const roundedClasses: Record<FieldSize, string> = {
      xs: 'rounded-md',
      sm: 'rounded-lg',
      md: 'rounded-lg',
      lg: 'rounded-xl',
      xl: 'rounded-xl',
    };

    const textareaNode = (
      <div className="relative w-full">
        <textarea
          ref={ref}
          id={identifier.id || textareaId}
          name={name}
          value={value}
          defaultValue={defaultValue}
          onChange={handleChange}
          rows={rows}
          maxLength={maxLength}
          placeholder={placeholder}
          disabled={disabled}
          readOnly={readOnly}
          required={required}
          className={cn(
            'w-full transition-colors text-slate-800 placeholder-slate-400 focus:outline-none resize-y',
            identifier.className,
            roundedClasses[resolvedSize],
            sizeClasses[resolvedSize],
            error
              ? 'bg-rose-50/20 border border-rose-300 focus:border-rose-500 focus:ring-1 focus:ring-rose-500 text-rose-900'
              : 'bg-white hover:border-slate-400 focus:border-emerald-600 focus:ring-1 focus:ring-emerald-600 border border-slate-300',
            disabled && 'opacity-60 bg-slate-50/80 cursor-not-allowed border-slate-200',
            fieldConfig?.className,
            className
          )}
          data-rakit="textarea"
          data-size={resolvedSize}
          {...props}
        />

        <div className="flex items-center justify-between mt-1 px-1">
          {clearable && hasValue && !disabled && !readOnly ? (
            <button
              type="button"
              onClick={handleClear}
              className="inline-flex items-center gap-1 text-[11px] text-slate-400 hover:text-slate-600 transition-colors cursor-pointer"
            >
              <X className="w-3 h-3" />
              <span>Bersihkan</span>
            </button>
          ) : (
            <span />
          )}

          {showCount && (
            <span className="text-[11px] font-mono text-slate-400 select-none ml-auto">
              {currentLength}
              {maxLength ? ` / ${maxLength}` : ' karakter'}
            </span>
          )}
        </div>
      </div>
    );

    if (label || error || helperText || hint) {
      return (
        <FieldWrapper
          htmlFor={textareaId}
          label={label}
          error={error}
          helperText={helperText}
          hint={hint}
          required={required}
          optional={optional}
          disabled={disabled}
          size={resolvedSize}
          layout={layout}
          className={wrapperClassName}
        >
          {textareaNode}
        </FieldWrapper>
      );
    }

    return textareaNode;
  }
);

TextArea.displayName = 'TextArea';

// ============================================================================
// TYPES & INTERFACES
// ============================================================================
export type { TextAreaProps } from '../../../../types/ui/field/textArea.types';
