import { useEffect, useRef } from 'react';
import { createPortal } from 'react-dom';
import { cn } from '../../../utils/ui/cn';
import { useRakitConfig, getComponentIdentifier } from '../../../config/RakitContext';
import { DrawerHeader } from './DrawerHeader';
import { DrawerTitle } from './DrawerTitle';
import { DrawerDescription } from './DrawerDescription';
import { DrawerBody } from './DrawerBody';
import { DrawerFooter } from './DrawerFooter';
import type { DrawerProps, DrawerPlacement, DrawerSize } from '../../../types/ui/drawer.types';

const horizontalSizeClasses: Record<DrawerSize, string> = {
  sm: 'w-72 max-w-[85vw]',
  md: 'w-80 max-w-[85vw]',
  lg: 'w-96 max-w-[90vw]',
  xl: 'w-[480px] max-w-[95vw]',
  full: 'w-screen',
};

const verticalSizeClasses: Record<DrawerSize, string> = {
  sm: 'h-64 max-h-[85vh]',
  md: 'h-80 max-h-[85vh]',
  lg: 'h-96 max-h-[90vh]',
  xl: 'h-[480px] max-h-[95vh]',
  full: 'h-screen',
};

const placementClasses: Record<DrawerPlacement, string> = {
  left: 'inset-y-0 left-0 animate-in slide-in-from-left duration-200 border-r',
  right: 'inset-y-0 right-0 animate-in slide-in-from-right duration-200 border-l',
  top: 'inset-x-0 top-0 animate-in slide-in-from-top duration-200 border-b',
  bottom: 'inset-x-0 bottom-0 animate-in slide-in-from-bottom duration-200 border-t',
};

export function Drawer({
  id,
  isOpen,
  onClose,
  placement = 'right',
  size = 'md',
  title,
  description,
  icon,
  children,
  footer,
  className = '',
  contentClassName = '',
  closeOnEsc = true,
  closeOnOverlayClick = true,
  showCloseButton = true,
  backdropBlur = true,
  bordered = true,
}: DrawerProps) {
  const config = useRakitConfig();
  const identifier = getComponentIdentifier('drawer', config, id);
  const drawerOverride = config.components?.drawer;
  const drawerRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    if (!isOpen) return;

    const handleKeyDown = (e: KeyboardEvent) => {
      if (closeOnEsc && e.key === 'Escape') {
        onClose();
      }
    };

    window.addEventListener('keydown', handleKeyDown);
    const originalOverflow = document.body.style.overflow;
    document.body.style.overflow = 'hidden';

    return () => {
      window.removeEventListener('keydown', handleKeyDown);
      document.body.style.overflow = originalOverflow;
    };
  }, [isOpen, closeOnEsc, onClose]);

  if (!isOpen || typeof document === 'undefined') return null;

  const isVertical = placement === 'top' || placement === 'bottom';
  const sizeClass = isVertical ? verticalSizeClasses[size] : horizontalSizeClasses[size];

  const content = (
    <div
      id={identifier.id}
      data-rakit={identifier['data-rakit']}
      className={cn(
        'rakit-drawer fixed inset-0 z-50 overflow-hidden',
        identifier.className,
        drawerOverride?.className,
        className
      )}
      style={drawerOverride?.style}
      role="dialog"
      aria-modal="true"
    >
      {/* Backdrop Overlay */}
      <div
        className={cn(
          'rakit-drawer-overlay fixed inset-0 bg-slate-900/60 transition-opacity animate-in fade-in duration-200',
          backdropBlur && 'backdrop-blur-xs'
        )}
        onClick={() => {
          if (closeOnOverlayClick) onClose();
        }}
        aria-hidden="true"
      />

      {/* Slide-over Content Panel */}
      <div
        ref={drawerRef}
        onClick={(e) => e.stopPropagation()}
        className={cn(
          'rakit-drawer-content fixed bg-white dark:bg-slate-900 text-slate-900 dark:text-slate-100 shadow-2xl flex flex-col focus:outline-hidden',
          bordered && 'border-slate-200 dark:border-slate-800',
          placementClasses[placement],
          sizeClass,
          contentClassName
        )}
      >
        {(title || showCloseButton) && (
          <DrawerHeader
            title={title}
            description={description}
            icon={icon}
            showCloseButton={showCloseButton}
            onClose={showCloseButton ? onClose : undefined}
          />
        )}

        {/* If title and footer are not used, allow children full control (like for Sidebar), otherwise wrap in DrawerBody */}
        {title || footer ? (
          <DrawerBody className="p-0 flex flex-col flex-1 min-h-0">{children}</DrawerBody>
        ) : (
          <div className="flex-1 flex flex-col min-h-0 overflow-hidden">{children}</div>
        )}

        {footer && <DrawerFooter>{footer}</DrawerFooter>}
      </div>
    </div>
  );

  return createPortal(content, document.body);
}

// Compound component attachments
Drawer.Header = DrawerHeader;
Drawer.Title = DrawerTitle;
Drawer.Description = DrawerDescription;
Drawer.Body = DrawerBody;
Drawer.Footer = DrawerFooter;
