import { useState } from 'react';

import { Badge } from '../badge';

import { cn } from '../../../utils/ui/cn';

import type {
  TabItem,
  TabsProps,
  TabSize,
  TabVariant,
  TabOrientation,
} from '../../../types/ui/tabs.types';

const sizeStyles: Record<TabSize, { button: string; icon: string; text: string }> = {
  xs: {
    button: 'px-2 py-0.5 text-xs gap-1',
    icon: 'w-3 h-3',
    text: 'text-xs',
  },
  sm: {
    button: 'px-2.5 py-1 text-xs gap-1.5',
    icon: 'w-3.5 h-3.5',
    text: 'text-xs',
  },
  md: {
    button: 'px-3 py-1.5 text-sm gap-2',
    icon: 'w-4 h-4',
    text: 'text-sm',
  },
  lg: {
    button: 'px-4 py-2 text-base gap-2.5',
    icon: 'w-4.5 h-4.5',
    text: 'text-base',
  },
};

const getVariantListStyles = (
  variant: TabVariant,
  isDark: boolean,
  orientation: TabOrientation,
  borderPosition: 'left' | 'right'
): string => {
  const isVertical = orientation === 'vertical';

  if (isVertical) {
    if (variant === 'underline') {
      const borderSide = borderPosition === 'left' ? 'border-l' : 'border-r';
      return cn(
        'flex flex-col gap-1 bg-transparent p-0',
        borderSide,
        isDark ? 'border-slate-800' : 'border-slate-200'
      );
    }
    if (variant === 'bordered') {
      return cn(
        'flex flex-col p-1 rounded-xl gap-1 border',
        isDark
          ? 'border-slate-700/80 bg-slate-900'
          : 'border-slate-200 bg-white'
      );
    }
    // pills / default
    return cn(
      'flex flex-col p-1 rounded-xl gap-1',
      isDark
        ? 'bg-slate-800/80 border border-slate-700/60'
        : 'bg-slate-100/90'
    );
  }

  if (isDark) {
    switch (variant) {
      case 'underline':
        return 'border-b border-slate-800 gap-4 bg-transparent p-0';
      case 'bordered':
        return 'border border-slate-700/80 p-0.5 rounded-lg bg-slate-900 gap-1';
      case 'pills':
      case 'default':
      default:
        return 'bg-slate-800/80 border border-slate-700/60 p-0.5 rounded-lg gap-1';
    }
  }

  switch (variant) {
    case 'pills':
      return 'bg-slate-100/90 p-1 rounded-xl gap-1';
    case 'default':
      return 'bg-slate-200/70 p-1 rounded-xl gap-1';
    case 'underline':
      return 'border-b border-slate-200 gap-4 bg-transparent p-0';
    case 'bordered':
      return 'border border-slate-200 p-1 rounded-xl bg-white gap-1';
    default:
      return 'bg-slate-100/90 p-1 rounded-xl gap-1';
  }
};

export function Tabs<T extends string = string>({
  items = [],
  value,
  defaultValue,
  onChange,
  variant = 'default',
  size = 'md',
  orientation = 'horizontal',
  borderPosition = 'right',
  theme = 'light',
  className = '',
  tabListClassName = '',
  contentClassName = '',
  fullWidth = false,
  extra,
  children,
}: TabsProps<T>) {
  const isDark = theme === 'dark';
  const isVertical = orientation === 'vertical';
  const initialTab = defaultValue || items[0]?.id || ('' as T);
  const [internalValue, setInternalValue] = useState<T>(initialTab);

  const activeTabId = value !== undefined ? value : internalValue;

  const handleTabClick = (tab: TabItem<T>) => {
    if (tab.disabled) return;
    if (value === undefined) {
      setInternalValue(tab.id);
    }
    onChange?.(tab.id);
  };

  const activeItem = items.find((item) => item.id === activeTabId);

  const getButtonStyles = (tab: TabItem, isActive: boolean) => {
    const sizeConfig = sizeStyles[size];
    const base = cn(
      'inline-flex items-center font-medium transition-all select-none',
      isVertical ? 'justify-start text-left w-full' : 'justify-center',
      sizeConfig.button,
      fullWidth && !isVertical ? 'flex-1' : '',
      tab.disabled ? 'opacity-40 cursor-not-allowed' : 'cursor-pointer'
    );

    if (isVertical && variant === 'underline') {
      const borderSideActive = borderPosition === 'left' ? 'border-l-2 -ml-px pl-2.5' : 'border-r-2 -mr-px pr-2.5';
      const borderSideInactive = borderPosition === 'left' ? 'border-l-2 border-transparent pl-2.5' : 'border-r-2 border-transparent pr-2.5';

      if (isDark) {
        return cn(
          base,
          'rounded-none',
          isActive
            ? cn(borderSideActive, 'border-emerald-400 text-white font-semibold')
            : cn(borderSideInactive, 'text-slate-400 hover:text-white hover:border-slate-700')
        );
      }

      return cn(
        base,
        'rounded-none',
        isActive
          ? cn(borderSideActive, 'border-emerald-600 text-emerald-800 font-semibold')
          : cn(borderSideInactive, 'text-slate-500 hover:text-slate-800 hover:border-slate-300')
      );
    }

    if (isDark) {
      switch (variant) {
        case 'underline':
          return cn(
            base,
            'rounded-none border-b-2 -mb-px pb-2',
            isActive
              ? 'border-emerald-400 text-white font-semibold'
              : 'border-transparent text-slate-400 hover:text-white hover:border-slate-700'
          );
        case 'pills':
        case 'default':
        case 'bordered':
        default:
          return cn(
            base,
            'rounded-md',
            isActive
              ? 'bg-slate-700 text-white shadow-2xs font-semibold'
              : 'text-slate-400 hover:text-white hover:bg-slate-800/50'
          );
      }
    }

    switch (variant) {
      case 'underline':
        return cn(
          base,
          'rounded-none border-b-2 -mb-px pb-2',
          isActive
            ? 'border-emerald-600 text-emerald-800 font-semibold'
            : 'border-transparent text-slate-500 hover:text-slate-800 hover:border-slate-300'
        );
      case 'pills':
      case 'default':
      case 'bordered':
      default:
        return cn(
          base,
          'rounded-lg',
          isActive
            ? 'bg-white text-slate-900 shadow-2xs font-semibold'
            : 'text-slate-600 hover:text-slate-900 hover:bg-slate-200/50'
        );
    }
  };

  const hasContent = Boolean(activeItem?.content || children);

  return (
    <div
      className={cn(
        'w-full',
        isVertical ? (hasContent ? 'flex flex-row gap-6 items-start' : 'flex flex-col') : 'flex flex-col',
        className
      )}
    >
      <div
        className={cn(
          'flex items-center gap-2.5',
          isVertical ? 'flex-col items-stretch w-full sm:w-auto shrink-0' : 'flex-wrap justify-between'
        )}
      >
        <div
          role="tablist"
          aria-orientation={orientation}
          className={cn(
            isVertical ? 'flex flex-col' : 'inline-flex flex-wrap items-center',
            getVariantListStyles(variant, isDark, orientation, borderPosition),
            fullWidth && !isVertical ? 'w-full' : '',
            tabListClassName
          )}
        >
          {items.map((tab) => {
            const isActive = tab.id === activeTabId;
            return (
              <button
                key={tab.id}
                role="tab"
                type="button"
                aria-selected={isActive}
                disabled={tab.disabled}
                onClick={() => handleTabClick(tab)}
                className={getButtonStyles(tab, isActive)}
              >
                {tab.icon && <span className="shrink-0">{tab.icon}</span>}
                <span className="truncate">{tab.label}</span>
                {tab.badge !== undefined && (
                  <Badge
                    variant={tab.badgeVariant || (isActive ? 'success' : 'default')}
                    size="xs"
                    className="ml-auto"
                  >
                    {tab.badge}
                  </Badge>
                )}
              </button>
            );
          })}
        </div>

        {extra && <div className="shrink-0">{extra}</div>}
      </div>

      {hasContent && (
        <div
          role="tabpanel"
          className={cn(isVertical ? 'flex-1 min-w-0' : 'mt-3 w-full', contentClassName)}
        >
          {activeItem?.content || children}
        </div>
      )}
    </div>
  );
}

// ============================================================================
// TYPES & INTERFACES
// ============================================================================
export type {
  TabItem,
  TabsProps,
  TabSize,
  TabVariant,
  TabOrientation,
} from '../../../types/ui/tabs.types';

