import { X } from 'lucide-react';
import { cn } from '../../../utils/ui/cn';
import { DrawerTitle } from './DrawerTitle';
import { DrawerDescription } from './DrawerDescription';
import type { DrawerHeaderProps } from '../../../types/ui/drawer.types';

export function DrawerHeader({
  title,
  description,
  icon,
  showCloseButton = true,
  onClose,
  className = '',
  children,
  ...rest
}: DrawerHeaderProps) {
  return (
    <div
      className={cn(
        'rakit-drawer-header flex items-center justify-between px-5 py-4 border-b border-slate-100 dark:border-slate-800/80 shrink-0',
        className
      )}
      data-rakit="drawer-header"
      {...rest}
    >
      {children ? (
        children
      ) : (
        <div className="flex items-center gap-3 min-w-0">
          {icon && <div className="text-emerald-600 dark:text-emerald-400 shrink-0">{icon}</div>}
          <div className="min-w-0">
            {title && <DrawerTitle>{title}</DrawerTitle>}
            {description && <DrawerDescription>{description}</DrawerDescription>}
          </div>
        </div>
      )}

      {showCloseButton && onClose && (
        <button
          type="button"
          onClick={onClose}
          aria-label="Tutup Drawer"
          className="p-1.5 -mr-1 rounded-lg text-slate-400 hover:text-slate-700 hover:bg-slate-100 dark:text-slate-400 dark:hover:text-slate-200 dark:hover:bg-slate-800 transition-colors cursor-pointer"
        >
          <X className="w-4 h-4" />
        </button>
      )}
    </div>
  );
}
