import React from 'react';
import { BreadcrumbSeparatorProps, BreadcrumbSeparatorType } from '../../../types/ui/breadcrumb.types';

export const renderSeparatorNode = (separator: BreadcrumbSeparatorType = 'slash'): React.ReactNode => {
  if (React.isValidElement(separator)) {
    return separator;
  }

  switch (separator) {
    case 'chevron':
      return (
        <svg
          className="w-3.5 h-3.5 text-slate-400 dark:text-slate-500 shrink-0"
          fill="none"
          stroke="currentColor"
          viewBox="0 0 24 24"
          aria-hidden="true"
        >
          <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M9 5l7 7-7 7" />
        </svg>
      );
    case 'arrow':
      return (
        <svg
          className="w-3.5 h-3.5 text-slate-400 dark:text-slate-500 shrink-0"
          fill="none"
          stroke="currentColor"
          viewBox="0 0 24 24"
          aria-hidden="true"
        >
          <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M14 5l7 7m0 0l-7 7m7-7H3" />
        </svg>
      );
    case 'bullet':
      return <span className="text-slate-300 dark:text-slate-600 select-none">•</span>;
    case 'slash':
    default:
      return <span className="text-slate-300 dark:text-slate-600 select-none font-mono">/</span>;
  }
};

export const BreadcrumbSeparator: React.FC<BreadcrumbSeparatorProps> = ({
  children,
  className = '',
  ...props
}) => {
  return (
    <li
      role="presentation"
      aria-hidden="true"
      className={`rakit-breadcrumb-separator inline-flex items-center text-slate-400 dark:text-slate-500 select-none ${className}`}
      data-rakit="breadcrumb-separator"
      {...props}
    >
      {children || renderSeparatorNode('slash')}
    </li>
  );
};
