import { forwardRef } from 'react';
import { cn } from '../../../utils/ui/cn';

import type { LayoutContentProps } from '../../../types/ui/layout.types';

export const LayoutContent = forwardRef<HTMLElement, LayoutContentProps>(
  (
    {
      padded = true,
      className = '',
      children,
      ...props
    },
    ref
  ) => {
    return (
      <main
        ref={ref}
        className={cn(
          'rakit-layout-content flex-1 min-w-0 min-h-0 flex flex-col z-0',
          'overflow-y-auto overflow-x-hidden',
          padded && 'p-4 md:p-6',
          className
        )}
        {...props}
      >
        {children}
      </main>
    );
  }
);

LayoutContent.displayName = 'LayoutContent';

// ============================================================================
// TYPES & INTERFACES
// ============================================================================
export type { LayoutContentProps } from '../../../types/ui/layout.types';
