import React from 'react';
import {
  BreadcrumbProps,
  BreadcrumbSize,
} from '../../../types/ui/breadcrumb.types';
import { useRakitConfig, getComponentIdentifier } from '../../../config/RakitContext';
import { BreadcrumbItem } from './BreadcrumbItem';
import { BreadcrumbLink } from './BreadcrumbLink';
import { BreadcrumbPage } from './BreadcrumbPage';
import { BreadcrumbSeparator, renderSeparatorNode } from './BreadcrumbSeparator';

const SIZE_MAP: Record<BreadcrumbSize, string> = {
  xs: 'text-xs gap-1',
  sm: 'text-xs gap-1.5',
  md: 'text-sm gap-2',
  lg: 'text-base gap-2.5',
};

export interface BreadcrumbComponent extends React.FC<BreadcrumbProps> {
  Item: typeof BreadcrumbItem;
  Link: typeof BreadcrumbLink;
  Page: typeof BreadcrumbPage;
  Separator: typeof BreadcrumbSeparator;
}

export const Breadcrumb: BreadcrumbComponent = ({
  items,
  separator = 'slash',
  size = 'sm',
  maxItems,
  id,
  className = '',
  children,
  ...props
}) => {
  const config = useRakitConfig();
  const identifier = getComponentIdentifier('breadcrumb', config, id);

  const navClasses = [
    'rakit-breadcrumb',
    identifier.className,
    className,
  ]
    .filter(Boolean)
    .join(' ');

  const listClasses = [
    'flex flex-wrap items-center',
    SIZE_MAP[size],
    'text-slate-500 dark:text-slate-400 font-medium',
  ]
    .filter(Boolean)
    .join(' ');

  return (
    <nav
      id={identifier.id}
      data-rakit={identifier['data-rakit']}
      aria-label="Breadcrumb"
      className={navClasses}
      {...props}
    >
      <ol className={listClasses}>
        {items && items.length > 0 ? (
          items.map((item, index) => {
            const isLast = index === items.length - 1;
            const isItemActive = item.active ?? isLast;

            return (
              <React.Fragment key={item.id || index}>
                <BreadcrumbItem active={isItemActive}>
                  {item.icon && <span className="inline-flex shrink-0">{item.icon}</span>}
                  {isItemActive ? (
                    <BreadcrumbPage>{item.label}</BreadcrumbPage>
                  ) : (
                    <BreadcrumbLink href={item.href} onClick={item.onClick}>
                      {item.label}
                    </BreadcrumbLink>
                  )}
                </BreadcrumbItem>
                {!isLast && (
                  <BreadcrumbSeparator>
                    {renderSeparatorNode(separator)}
                  </BreadcrumbSeparator>
                )}
              </React.Fragment>
            );
          })
        ) : (
          children
        )}
      </ol>
    </nav>
  );
};

Breadcrumb.Item = BreadcrumbItem;
Breadcrumb.Link = BreadcrumbLink;
Breadcrumb.Page = BreadcrumbPage;
Breadcrumb.Separator = BreadcrumbSeparator;
