import React from 'react';
import { TextProps, TextSize, TextWeight, TextColor, TextVariant } from '../../../types/ui/typography.types';
import { useRakitConfig, getComponentIdentifier } from '../../../config/RakitContext';

const SIZE_MAP: Record<TextSize, string> = {
  xs: 'text-xs',
  sm: 'text-sm',
  md: 'text-base',
  lg: 'text-lg',
  xl: 'text-xl',
};

const WEIGHT_MAP: Record<TextWeight, string> = {
  light: 'font-light',
  normal: 'font-normal',
  medium: 'font-medium',
  semibold: 'font-semibold',
  bold: 'font-bold',
  extrabold: 'font-extrabold',
};

const COLOR_MAP: Record<TextColor, string> = {
  default: 'text-slate-900 dark:text-slate-100',
  secondary: 'text-slate-700 dark:text-slate-300',
  muted: 'text-slate-500 dark:text-slate-400',
  primary: 'text-emerald-600 dark:text-emerald-400',
  success: 'text-emerald-600 dark:text-emerald-400',
  warning: 'text-amber-600 dark:text-amber-400',
  danger: 'text-rose-600 dark:text-rose-400',
  info: 'text-sky-600 dark:text-sky-400',
  inverse: 'text-white dark:text-slate-950',
};

const VARIANT_MAP: Record<TextVariant, string> = {
  body: '',
  lead: 'text-lg md:text-xl font-normal text-slate-600 dark:text-slate-300 leading-relaxed',
  caption: 'text-xs text-slate-500 dark:text-slate-400 tracking-wide',
  label: 'text-xs font-semibold uppercase tracking-wider text-slate-500 dark:text-slate-400',
  mono: 'font-mono text-sm tracking-tight',
};

export const Text: React.FC<TextProps> = ({
  as: Component = 'span',
  size = 'md',
  weight = 'normal',
  color = 'default',
  variant = 'body',
  truncate = false,
  italic = false,
  underline = false,
  delete: isDeleted = false,
  mark = false,
  id,
  className = '',
  children,
  ...props
}) => {
  const config = useRakitConfig();
  const identifier = getComponentIdentifier('text', config, id);

  const classes = [
    'rakit-text',
    identifier.className,
    SIZE_MAP[size],
    WEIGHT_MAP[weight],
    COLOR_MAP[color],
    VARIANT_MAP[variant],
    truncate ? 'truncate block' : '',
    italic ? 'italic' : '',
    underline ? 'underline underline-offset-4' : '',
    isDeleted ? 'line-through opacity-75' : '',
    mark ? 'bg-amber-100 dark:bg-amber-950/60 px-1 py-0.5 rounded text-amber-900 dark:text-amber-200' : '',
    className,
  ]
    .filter(Boolean)
    .join(' ');

  return (
    <Component
      id={identifier.id}
      data-rakit={identifier['data-rakit']}
      className={classes}
      {...props}
    >
      {children}
    </Component>
  );
};
