import { isValidElement } from 'react';
import { cn } from '../../../utils/ui/cn';
import { useSidebar } from './SidebarContext';
import { Badge } from '../badge';
import type { SidebarItemProps } from '../../../types/ui/sidebar.types';

export function SidebarItem({
  icon: Icon,
  label,
  active = false,
  badge,
  badgeVariant,
  indicator = true,
  disabled = false,
  title,
  as: Component = 'button',
  href,
  onClick,
  className = '',
  children,
  ...rest
}: SidebarItemProps) {
  const { collapsed } = useSidebar();

  const Element = href ? 'a' : Component;

  const defaultTitle =
    title || (collapsed && typeof label === 'string' ? label : undefined);

  const resolvedBadgeVariant =
    badgeVariant || (active ? 'primary' : 'default');

  const renderIcon = () => {
    if (!Icon) return null;
    if (isValidElement(Icon)) return Icon;
    const IconComponent = Icon as React.ComponentType<{ className?: string }>;
    return (
      <IconComponent
        className={cn(
          'w-4 h-4 shrink-0 transition-colors',
          active
            ? 'text-emerald-700 dark:text-emerald-400'
            : 'text-slate-400 group-hover:text-slate-600 dark:text-slate-500 dark:group-hover:text-slate-300'
        )}
      />
    );
  };

  return (
    <Element
      type={Element === 'button' ? 'button' : undefined}
      href={href}
      onClick={disabled ? undefined : (onClick as any)}
      disabled={disabled}
      title={defaultTitle}
      aria-current={active ? 'page' : undefined}
      data-rakit="sidebar-item"
      data-active={active}
      data-collapsed={collapsed}
      className={cn(
        // Base structure
        'group relative flex items-center transition-all duration-150 font-medium select-none cursor-pointer rounded-xl',
        // Layout based on collapsed state
        collapsed
          ? 'justify-center px-1.5 py-2 h-9 w-full'
          : 'justify-between pl-3 pr-2.5 py-2 min-h-9 w-full text-xs font-sans tracking-tight',
        // Theme variants & active state (Emerald light-tint harmonized with Rakit-UI Button)
        active
          ? 'bg-emerald-50/90 text-emerald-950 font-semibold shadow-2xs border border-emerald-300/80 ring-1 ring-emerald-400/20 dark:bg-emerald-950/40 dark:text-emerald-200 dark:border-emerald-700/60'
          : 'text-slate-600 dark:text-slate-400 hover:bg-slate-100/90 dark:hover:bg-slate-800/80 hover:text-slate-900 dark:hover:text-slate-100 border border-transparent',
        // Disabled state
        disabled && 'opacity-50 pointer-events-none cursor-not-allowed',
        className
      )}
      {...(rest as any)}
    >
      {/* Active Indicator Line */}
      {active && indicator && (
        <span
          className="absolute left-0 top-1.5 bottom-1.5 w-1 rounded-r-full bg-emerald-600 dark:bg-emerald-400"
          aria-hidden="true"
        />
      )}

      {/* Main Content (Icon + Label) */}
      <div
        className={cn(
          'flex items-center gap-2.5 min-w-0',
          collapsed && 'justify-center'
        )}
      >
        {renderIcon()}
        {!collapsed && (
          <span className="truncate leading-normal">{label}</span>
        )}
      </div>

      {/* Badge (Hidden when collapsed) */}
      {!collapsed && badge !== undefined && badge !== null && (
        <div className="shrink-0 ml-1.5">
          {typeof badge === 'string' || typeof badge === 'number' ? (
            <Badge variant={resolvedBadgeVariant} size="xs" className="text-[10px]">
              {badge}
            </Badge>
          ) : (
            badge
          )}
        </div>
      )}

      {children}
    </Element>
  );
}
