import React from 'react';
import { BreadcrumbLinkProps } from '../../../types/ui/breadcrumb.types';

export const BreadcrumbLink: React.FC<BreadcrumbLinkProps> = ({
  href,
  onClick,
  as: Component = 'a',
  className = '',
  children,
  ...props
}) => {
  const classes = [
    'rakit-breadcrumb-link inline-flex items-center gap-1.5 transition-colors duration-150',
    'hover:text-slate-900 dark:hover:text-slate-100 cursor-pointer',
    className,
  ]
    .filter(Boolean)
    .join(' ');

  return (
    <Component
      href={href}
      onClick={onClick}
      className={classes}
      data-rakit="breadcrumb-link"
      {...props}
    >
      {children}
    </Component>
  );
};
