import Prism from 'prismjs';
import 'prismjs/components/prism-markup';
import 'prismjs/components/prism-css';
import 'prismjs/components/prism-javascript';
import 'prismjs/components/prism-typescript';
import 'prismjs/components/prism-jsx';
import 'prismjs/components/prism-tsx';
import 'prismjs/components/prism-json';

export function highlightCode(code: string, language: string): string {
  if (!code) return '';

  const normalizedLang = (language || 'text').toLowerCase().trim();

  let grammar = Prism.languages[normalizedLang];
  let langKey = normalizedLang;

  if (!grammar) {
    switch (normalizedLang) {
      case 'ts':
      case 'typescript':
        grammar = Prism.languages.typescript;
        langKey = 'typescript';
        break;
      case 'tsx':
        grammar = Prism.languages.tsx;
        langKey = 'tsx';
        break;
      case 'js':
      case 'javascript':
        grammar = Prism.languages.javascript;
        langKey = 'javascript';
        break;
      case 'jsx':
        grammar = Prism.languages.jsx;
        langKey = 'jsx';
        break;
      case 'html':
      case 'xml':
      case 'svg':
        grammar = Prism.languages.markup;
        langKey = 'markup';
        break;
      case 'css':
        grammar = Prism.languages.css;
        langKey = 'css';
        break;
      case 'json':
        grammar = Prism.languages.json;
        langKey = 'json';
        break;
      default:
        grammar = Prism.languages.markup;
        langKey = 'markup';
        break;
    }
  }

  try {
    return Prism.highlight(code, grammar || Prism.languages.markup, langKey);
  } catch {
    // Fallback: safe HTML escape
    return code
      .replace(/&/g, '&amp;')
      .replace(/</g, '&lt;')
      .replace(/>/g, '&gt;')
      .replace(/"/g, '&quot;')
      .replace(/'/g, '&#039;');
  }
}
